quests[8383] = { id = 8383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remember Alterac Valley!", progress = "The Battle in Alterac Valley rages on, {name}!  Have you done your part as of late, {name}?", completion = "You continue to honor the Alliance, {name}.  The Horde will be crushed before long if we keep our efforts up." }
quests[8384] = { id = 8384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming Arathi Basin", progress = "The war against the Horde is quickly depleting our supplies, {name}.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, {class}!  Your efforts will help to provide the Alliance with the resources it needs." }
quests[8385] = { id = 8385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Concerted Efforts", progress = "Ah, {name}.  I hope you continue to lend your experience to the different battlefronts.  A lot of our lads and lasses in the field look up to seasoned veterans like you.", completion = "You live up to yer reputation, {name}.  Without people like you, the Alliance wouldn't stand a chance against the savage forces of the Horde." }
quests[8386] = { id = 8386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight for Warsong Gulch", progress = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, {name}?", completion = "Good work, {name}.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day." }
quests[8387] = { id = 8387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invaders of Alterac Valley", progress = "The battle for Alterac rages on!  You must return to Alterac Valley and once more drive the invaders out of Frostwolf territory, {name}!", completion = "Good work, {name}!  You should be proud of yourself.  The Alliance invaders must be expelled from Alterac!" }
quests[8388] = { id = 8388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Great Honor", progress = "Many brave fighters look up to you, {name}.  You continue to be an example for all in the fight against the Alliance.  What news do you bring from your journeys?", completion = "You continue to honor the Horde, {name}.  I'm glad to see you haven't turned soft." }
quests[8389] = { id = 8389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Warsong Gulch", progress = "The battle in Warsong Gulch rages on, {name}.  Do your part to drive the Silverwing Sentinels out of our lands!", completion = "Well done, {class}!  You've helped ensure the Horde's ownership over Warsong Gulch!" }
quests[8390] = { id = 8390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conquering Arathi Basin", progress = "The war against the Alliance scum demands resources, {name}! We cannot allow our stockpiles to run dry in the middle of a battle.  Continue to ensure Arathi Basin remains in our hands!", completion = "Excellent work, {name}!  As long as Arathi Basin stays under our control our supplies will be well stocked." }
quests[8391] = { id = 8391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming Arathi Basin", progress = "The war against the Horde is quickly depleting our supplies, {name}.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, {class}!  Your efforts will help provide the Alliance with the resources it needs." }
quests[8392] = { id = 8392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming Arathi Basin", progress = "The war against the Horde is quickly depleting our supplies, {name}.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, {class}!  Your efforts will help provide the Alliance with the resources it needs." }
quests[8393] = { id = 8393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming Arathi Basin", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, {name}.", sourceObjective = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[8394] = { id = 8394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claiming Arathi Basin", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, {name}.", sourceObjective = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
