quests[8404] = { id = 8404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight for Warsong Gulch", progress = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, {name}?", completion = "Good work, {name}.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day." }
quests[8405] = { id = 8405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight for Warsong Gulch", progress = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, {name}?", completion = "Good work, {name}.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day." }
