quests[8409] = { id = 8409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruined Kegs", description = "The rotten eggs have been successfully placed inside the keg.  Future batches of ale from the Southshore Inn are sure to be ruined!\n\nYou should now report back to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade and report your success.", sourceObjective = "Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.", completion = "Ah, success!  You've shown true Hallow's End spirit - FORSAKEN spirit, I should say!\n\n<Darkcaller Yanka laughs and rubs her hands together.>\n\nI revel in the fact that Southshore must now feast on bad ale or go without!  As for you, take these treats.  I believe you will find good use for them!", sourceObjectiveStatus = "unverified-source-field" }
quests[8410] = { id = 8410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Mastery", description = "Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready.\n\nTo find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.", sourceObjective = "Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.", progress = "What you got for me, {class}?", completion = "Excellent, mon.  Now we be talkin'.", sourceObjectiveStatus = "unverified-source-field" }
quests[8411] = { id = 8411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Elements", description = "Welcome, {class}.  You bring me the elements and then we do the talkin'.\n\nThe fire, the air, the water, and the earth I be needin' before I trust ya, mon.  I gots to know you be knowledgeable.", sourceObjective = "Bring the elements earth, air, fire and water to Bath'rah the Windwatcher.", progress = "Where's the elements, mon?", completion = "These be the elements I need.  Now we talk.", sourceObjectiveStatus = "unverified-source-field" }
quests[8412] = { id = 8412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit Totem", description = "The elemental spirits of this place don't be likin' me any more.\n\nYou know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal.\n\nIn the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one.", sourceObjective = "Bring the pieces for the spirit totem to Bath'rah the Windwatcher.", progress = "The spirits know what we're up to, and they been tryin' to kill me!  I hope you got the parts.", completion = "Great, mon!  Let's try it out....", sourceObjectiveStatus = "unverified-source-field" }
quests[8413] = { id = 8413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Voodoo", description = "The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.\n\nThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.", sourceObjective = "Bring the voodoo feathers to Bath'rah the Windwatcher.", progress = "Where's the feathers, mon?", completion = "It's about time this troll got a full night's rest!  The spirit totem will watch over me.\n\nI been a long time collectin' things, maybe you want somethin' for all your trouble?", sourceObjectiveStatus = "unverified-source-field" }
quests[8414] = { id = 8414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dispelling Evil", description = "Greetings, {class}.  Crusaders like you are a welcome sight in these desolate reaches.\n\nYour holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here.\n\nOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already.", sourceObjective = "Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.", progress = "What evil have you brought me?", completion = "There is risk in dispelling the evil from a scourgestone, for it attracts the attention of undead for countless miles.  But you are strong in the Light, {name}, and I do not fear for you...", sourceObjectiveStatus = "unverified-source-field" }
quests[8415] = { id = 8415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chillwind Camp", description = "Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, {name}.  You can find him at Chillwind Camp in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!", sourceObjective = "Speak to Commander Ashlam Valorfist at Chillwind Camp.", completion = "Very well, {class}!  Let's see what you're made of.", sourceObjectiveStatus = "unverified-source-field" }
quests[8416] = { id = 8416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inert Scourgestones", description = "The evil has been purged from the stones, {name}.\n\nI am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire.", sourceObjective = "Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point.", progress = "Was Thal'danis able to cleanse the scourgestones?", completion = "You have done as I asked without question, {name}.\n\nTrust is achieved, it seems.  Perhaps I can reveal our plan in more detail to you now.", sourceObjectiveStatus = "unverified-source-field" }
quests[8417] = { id = 8417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Troubled Spirit", description = "In the Blasted Lands, there is a troubled spirit who was once a great hero of the horde.  A warrior's honor does not die with the body, and it would serve you well to speak with him.", sourceObjective = "Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands.", completion = "So, you have come to alleviate my pain.  I wish you could simply strike me down, but it is not that simple...", sourceObjectiveStatus = "unverified-source-field" }
quests[8418] = { id = 8418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging the Mightstone", description = "Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, {name}.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.\n\nIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.", sourceObjective = "Collect Amber, Blue, and Green Voodoo Feathers from the trolls of Sunken Temple.", progress = "Have you slain the wretched trolls?", completion = "This is excellent, {name}.  I would say I am surprised, but I knew without question that you wouldn't let us down.\n\nIt is my honor to bestow one of the Holy Mightstones to you.  Use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[8419] = { id = 8419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Imp's Request", description = "{name}, an imp in Felwood by the name of Impsy has requested your presence.  It is somewhat strange, as he has asked that you bring a piece of felcloth as a sign of good faith.  Considering the power you already wield as a warlock, I can only assume you know the satyrs of Felwood carry this felcloth.\n\nYou can find Impsy just north of the Bloodvenom Falls, which I've heard is quite lovely this time of year.", sourceObjective = "Bring a piece of felcloth to Impsy in Felwood.", progress = "Do you have my felcloth?", completion = "What a splendid {class} you are!\n\n\n\nOh how I love the feel of it, the way it burns your skin and weaves evil thoughts through the mind...", sourceObjectiveStatus = "unverified-source-field" }
quests[8420] = { id = 8420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot and Itchy", description = "Maybe this sounds strange coming from an imp, but I'd like a pet of my own.  I really would.  It's just not fair that Niby gets me and I get nothing!\n\nIn fact, it doesn't even need to be a living pet.  I'd need something to start making it with, like some felcloth.  The satyrs here in Felwood sometimes have felcloth, so you'd just have to kill enough of them until you find some.  That doesn't sound so bad, does it?", sourceObjective = "Bring a piece of felcloth to Impsy in Felwood.", progress = "Do you have my felcloth?", completion = "Wow!  You are too kind.  Especially for a {class}!\n\n\n\nOh how I love the feel of it, the way it burns your skin and weaves evil thoughts through the mind...", sourceObjectiveStatus = "unverified-source-field" }
quests[8421] = { id = 8421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wrong Stuff", description = "Now that I have my felcloth, I can really begin making *my* pet.\n\nIt's going to need some eyes though.  Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes.  They're up north in the Irontree Woods.\n\nI'll also need some bloodvenom essence to give it that new demon smell.  The tainted oozes carry the essence, and they hang out right here near Niby and me.", sourceObjective = "Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.", progress = "Do you have the goods?", completion = "This will work so very well.", sourceObjectiveStatus = "unverified-source-field" }
quests[8422] = { id = 8422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trolls of a Feather", description = "My pet is almost done.  Now I just need something to stuff it with.\n\nOnly the voodoo feathers from the trolls in the sunken temple will do.  They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Kill them.  Kill them all.\n\nThis is no trivial task {name}, so I'll make it worth your while by giving you something of Niby's -- he probably doesn't need it anyhow.", sourceObjective = "Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", progress = "Did you bring the feathers?  This doll needs stuffed!", completion = "Wonderful, now my pet is complete!\n\n<Impsy quickly stuffs the doll and gives it a demonic hug.>\n\nOh, what an odd side effect these voodoo feathers have...", sourceObjectiveStatus = "unverified-source-field" }
quests[8423] = { id = 8423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage wrath 108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceFlavor = "wrath", sourceRevision = "108ede6c1fccfff2d41f291c49a032759a8a76c8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warrior Kinship", description = "<The Hero looks you over.>\n\nYou are a {class}, no doubt.  I would ask an honorable task of you, but I must test your strength.\n\nIt is said that Rexxar would measure the sharpness of his blades by killing a helboar with a single, swift strike.  Now I will measure your strength by killing them.", sourceObjective = "Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.", progress = "The burning spines of the helboar leave horrific scars.  Do not fear the pain and disfigurement, {class}, they are nothing compared to the prison to which I am bound.", completion = "I need no proof to know what you have done, {class}.  I can see the determination etched in your expression.", sourceObjectiveStatus = "unverified-source-field" }
